# 큐보 2권 사마귀로봇(교재 ?~?쪽) — 조립 프로그램(asmlib)으로 만든다.  ← 쪽 번호를 채운다 (교재 PDF 쪽 번호 = 교재 쪽 번호)
# 순서대로 만든다: 1단계 → 확인 → 2단계 → 확인 …  (뒤에서부터 만들거나 중간부터 시작하지 않는다)
# 각 단계: 교재 그림을 왼쪽→오른쪽, 위→아래로 읽고(부품·초록 원·화살표), get_step_context 로 직전 상태(쓴 부품·남은 부품·빈 구멍)를 본 뒤 적는다.
# 교재 LIST(부품 목록, 27개 종류):
#   2단블록 10
#   3단블록 4
#   15프레임 1
#   19프레임 4
#   25프레임 2
#   27프레임 2
#   29프레임 2
#   215프레임 2
#   39프레임 1
#   59프레임 4
#   515프레임 2
#   90도 프레임 2
#   135도 프레임 4
#   리벳 26
#   부시 12
#   T축 6
#   축 4
#   눈블록 2
#   작은바퀴 2
#   데코바퀴 2
#   작은기어 2
#   큰기어 4
#   DC모터 2
#   메인보드 1
#   리모컨 1
#   너트 4
#   12볼트 4
import json, sys
import numpy as np
from asmlib import *

A = Asm("cubo-2-mantis", "사마귀로봇", "교재 40~47쪽 · 사마귀로봇 (1~40단계)", camera={"target": [60, 20, 0], "radius": 380, "theta": 0.9, "phi": 1.0},
        listNote="만드는 중 — 단계가 끝나기 전까지 LIST 개수는 안 맞는 것이 정상", guideMode="mates")   # 연결점은 부품에 붙어 있고 결합할 자리일 때만 보인다(맞물림 방식, 사용자 지시 2026-10-04)
RELOCK = "--relock" in sys.argv   # 잠금 기록을 새로 만들 때(수정 지시는 이번 빌드에서 무시한다)
if not RELOCK: A.load_fixes("mantis_fixes.json")   # 관리자 수정 지시(앞 단계 수정 → 뒤 단계가 따라온다). 파일이 없으면 아무 일도 안 한다
A.load_links("mantis_links.json", relock=RELOCK)   # 좌표로 쓴 결합·절대 좌표로 놓은 판을 이름으로 잠가 두는 기록
UP = (0, 1, 0)

# ── 1 ── (교재 1: 첫 부품은 pt/place 로 직접 놓고, 나머지는 이름으로 결합한다)
# 예)  s1 = A.step("[교재 1] ...")
#      base = s1.place("315프레임", orient("315프레임", {"홀면 +y": "위"}), (75, 2.5, 0))
#      blk  = s1.attach("3단블록", orient("3단블록", {"돌기면 +z": "아래", "홀면 +y": "+Z"}), {"돌기면 +z 1": ("315프레임 1번", "홀면 +y 열14·줄1"), "돌기면 +z 3": ("315프레임 1번", "홀면 +y 열15·줄1")}, hover=45)
# 구멍·돌기는 이름(면 +축, 열·줄)으로 말한다(안내서 3-1절). 번호를 모르면 get_part_faces / get_step_context 로 본다.

# ── 번호 등록: 교재 40~47쪽을 훑어 정리 — 모든 번호를 noPart 뼈대로 둔다.
# 쪽 표: 40쪽 완성품 사진·LIST·1~2 / 41쪽 3~8 / 42쪽 9~14 / 43쪽 15~20 / 44쪽 21~26 / 45쪽 27~32 / 46쪽 33~38 / 47쪽 39~40+완성.
_PAGE = {**{n: 40 for n in (1, 2)}, **{n: 41 for n in range(3, 9)}, **{n: 42 for n in range(9, 15)}, **{n: 43 for n in range(15, 21)},
         **{n: 44 for n in range(21, 27)}, **{n: 45 for n in range(27, 33)}, **{n: 46 for n in range(33, 39)}, **{n: 47 for n in (39, 40)}}
SKEL = [A.step("[교재 %d] (작성 전) 교재 %d쪽 — 번호만 등록한 뼈대. 번호 작업 때 채운다." % (_n, _PAGE[_n]), noPart=True) for _n in range(1, 41)]
for _k in range(1, 41): A.steps[_k - 1].cam = (-0.79, 0.95, False, None, None, None); A.steps[_k - 1].camSrc = "guess"
# ── 창고 정리(04, 2026-10-15): 교재 40쪽부터 번호 순서대로 훑어 정했다. 창고 0 = 메인, 1~5 = 따로 만드는 자리.
#   1~4번 집게 팔 두 벌("4번까지 2개 만들기", 창고 1 에 세트로) → 5~11번 첫째 유닛(창고 1) / 12번 큰기어·T축 세트(창고 3) → 13번 합침(작은 번호 창고 1) / 14~18번 첫째 유닛 완성(창고 1)
#   19~25번 둘째 유닛(창고 2, 4번 팔 하나를 가져와 시작) / 26번 큰기어·T축 세트(창고 3) → 27번 합침(창고 2) / 28~31번 둘째 유닛 완성(창고 2) → 32번 "18 + 31" 합침(작은 번호 창고 1)
#   33~36번 몸 위·옆 판·눈(창고 1) / 37번 데코바퀴 세트 두 개(창고 2) → 38번 결합(창고 1) / 39~40번 메인보드·전선(창고 1)
_SLOT_MN = {**{i: 1 for i in range(1, 12)}, 12: 3, **{i: 1 for i in range(13, 19)}, **{i: 2 for i in range(19, 26)}, 26: 3, **{i: 2 for i in range(27, 32)}, **{i: 1 for i in range(32, 37)}, 37: 2, **{i: 1 for i in (38, 39, 40)}}
for _i, _sl in _SLOT_MN.items(): A.steps[_i - 1].kw["slot"] = _sl
_HIST_MN = {12: "📦 첫째 유닛(1~11번)을 창고 1에 두고, 창고 3에서 큰기어·T축 세트를 새로 시작(창고 2 는 1~4번 복사본이 보관 중이라 쓰지 않는다)",
            13: "창고 3의 큰기어·T축 세트(12번)를 가져와 창고 1의 첫째 유닛에 합쳐요(그림으로 판단)",
            19: "📦 첫째 유닛(1~18번)을 창고 1에 두고, 창고 1 에 보관한 4번 팔 하나를 가져와 창고 2에서 둘째 유닛을 새로 시작",
            26: "📦 둘째 유닛(19~25번)을 창고 2에 두고, 창고 3에서 큰기어·T축 세트를 새로 시작",
            27: "창고 3의 큰기어·T축 세트(26번)를 가져와 창고 2의 둘째 유닛에 합쳐요(그림으로 판단)",
            32: "창고 2의 둘째 유닛(31번)을 가져와 창고 1의 첫째 유닛(18번)과 합쳐요 — 번호표 '18 + 31', 번호가 작은 창고 1 에서 합친다",
            37: "📦 몸(1~36번)을 창고 1에 두고, 창고 2에서 데코바퀴 세트 두 개를 새로 시작",
            38: "창고 2의 데코바퀴 세트(37번)를 가져와 창고 1의 몸에 결합해요(그림으로 판단)"}
for _i, _h in _HIST_MN.items(): A.steps[_i - 1].kw["history"] = _h
# ── 1 ── 교재 40쪽 1 (읽은 것 2026-10-15, 그림에서 직접 읽음 — 사용자 지시 "이 판단은 어렵지 않다, 도구로 돌리지 말고 판단"): 215프레임 위 줄의 초록 링 2개 = 위쪽 오른쪽 끝에서 2번째·5번째 구멍(칸14·칸11, 3칸 간격), 135도 프레임 긴 팔의 리벳 2개도 3구멍 간격(h9·h6)
#   카메라가 보는 면(책): 판은 눕고 구멍 면(홀면)이 위, 긴 쪽 15칸이 왼쪽 아래 → 오른쪽 위(+X). 흰 135도 프레임은 판 **아래**에서 리벳 2개를 위로 꽂는다(2번 그림에서 판 위로 리벳 머리가 보임). 굽은 곳이 판 오른쪽 끝 밖으로 나오고 짧은 팔은 +Z(카메라 쪽 아래)로 휜다.
#   링→구멍: 위 줄(줄1, 먼 줄) — 리벳 h9(자유 끝) → 판 h11_1(칸11), 리벳 h6 → 판 h14_1(칸14). 프레임은 y축 180° 돌려서 h9→h4 가 +X, 짧은 팔 h3→h1 이 +Z.
s1 = SKEL[0]; s1.kw.pop("noPart", None)
s1.note = "[교재 1] 흰 135도 프레임 긴 팔의 리벳 2개를 215프레임 위 줄 구멍(오른쪽 끝에서 2번째·5번째)에 아래에서 올려 꽂아요. 흰 프레임은 판 아래에 있고 굽은 쪽이 판 오른쪽 끝 밖으로 나와요. ※ 1~4번은 2개 만들기."
R_FR1 = np.array([[-1, 0, 0], [0, 1, 0], [0, 0, -1]], float)   # 135도 프레임: y축 180° — 긴 팔(h9→h4)이 +X, 짧은 팔(h3→h1)이 +Z
FR1 = s1.place("135도 프레임", R_FR1, (66.5, 2.5, 6.5))        # 판 아래(y 0~5), 긴 팔이 z −5(판 위 줄 아래)
RV1 = [s1.attach("리벳", np.eye(3), {"돌기면 -y 1": (FR1, _h)}, rivet=True) for _h in ("h9", "h6")]   # 책이 꽂아 둔 모양(프레임에 서 있음) — 판이 위에서 내려오며 화살표 2개
PL1 = s1.recv("215프레임", np.eye(3), {"h11_1": (RV1[0], "p2"), "h14_1": (RV1[1], "p2")}, hover=60)
A.steps[0].cam = (-0.41, 0.73, False, None, None, None); A.steps[0].camSrc = "eye"   # 01_P 격자(30점, holefit DoG 23/30)에서 axes_fit 으로 계산: 오차 0.63px, roll −10.9°(책 그림이 기울어 그려짐 — 뷰어 카메라는 roll 이 없다)
# ── 2 ── 교재 40쪽 2 (읽은 것 2026-10-15 — 1번 결과 + 새 부품 2개: 책 2번에서 1번과 달라진 곳은 오른쪽 위 한 곳뿐이다)
#   책 2번: 1번 조립(판+135도 프레임, 리벳 머리 2개가 판 위로 보임)은 그대로. 새로 생긴 것 = ① 리벳 1개: 135도 프레임 짧은 팔의 둘째 구멍(h3, 판 끝에 걸친 구멍 h4 다음)에 서 있다(확대해서 센 값: 판 끝 구멍 h4·리벳 h3·h2·h1 = 보이는 구멍 4개 중 둘째) ② 90도 프레임 1개: 그 위에 떠 있고 팔 끝 구멍에 링이 있어 리벳을 받는다. 90도 프레임의 팔(3구멍)이 135도 짧은 팔의 h3·h2·h1 위에 겹치고, 모서리(h1)가 짧은 팔 끝 쪽, 둘째 팔은 카메라 쪽(+Z, −X)으로 꺾인다.
#   방향 카드: 135도 짧은 팔 방향 d1 = (+0.71 X, +0.71 Z). 90도 프레임: 끝 구멍 h3 → 모서리 h1 이 +d1, 모서리에서 둘째 팔(h1→h4→h5)이 d2 = (−0.71 X, +0.71 Z). R = y축 225°(local +z → −d1, local +x → d2).
s2 = SKEL[1]; s2.kw.pop("noPart", None)
s2.note = "[교재 2] 135도 프레임 짧은 팔의 둘째 구멍에 리벳을 꽂고, 그 위에 90도 프레임을 올려요. 90도 프레임의 한 팔 3구멍이 짧은 팔 위에 겹치고 다른 팔은 카메라 쪽으로 꺾여요. ※ 1~4번은 2개 만들기."
R_90_2 = np.array([[-0.7071067811865476, 0, -0.7071067811865476], [0, 1, 0], [0.7071067811865476, 0, -0.7071067811865476]], float)   # y축 225°
RV2 = s2.attach("리벳", np.eye(3), {"돌기면 -y 1": (FR1, "h3")}, rivet=True)             # 책이 꽂아 둔 모양(프레임에 서 있음) — 90도 프레임이 위에서 내려오며 화살표 1개
FR90 = s2.recv("90도 프레임", R_90_2, {"h3": (RV2, "p2")}, hover=60)
A.steps[1].cam = (-0.41, 0.73, False, None, None, None); A.steps[1].camSrc = "guess"   # 임시 — 책 2번과 같은 시점으로 화면에서 맞춘다
# ── 3 ── 교재 40쪽 3 (읽은 것 2026-10-15 — 2번 결과 + 새 135도 프레임 1개·리벳 3개: 책 3번에서 2번과 달라진 곳 = 위에서 내려오는 흰 135도 프레임과 그 아래 리벳 3개)
#   책 3번: 새 135도 프레임이 위에서 내려오고 링 3개(긴 팔 2개·짧은 팔 끝 1개)에 초록 선이 아래 리벳 3개로 간다. 리벳 3개 = 215프레임 위 줄에서 기존 리벳(칸11·칸14) 바로 옆 칸12·칸15(pegprobe 빈구멍: h12_1·h15_1 비어 있음) + 90도 프레임 모서리 구멍 h1.
#   새 135도 프레임은 1번 135도 프레임과 같은 자세(R_FR1)로 그 위에 겹친다 — 긴 팔 h8·h5 가 칸12·칸15(x 40·70), 짧은 팔 끝 h1 이 90도 프레임 h1(x 101). 링 간격(긴 팔 두 링 사이 구멍 2개 = 3칸)이 칸12↔칸15 와 같다.
s3 = SKEL[2]; s3.kw.pop("noPart", None)
s3.note = "[교재 3] 215프레임 위 줄 칸12·칸15 와 90도 프레임 모서리 구멍에 리벳 3개를 꽂고, 그 위에 135도 프레임을 올려요. 새 135도 프레임은 아래 135도 프레임과 같은 모양으로 겹쳐져요. ※ 1~4번은 2개 만들기."
RV3a = s3.attach("리벳", np.eye(3), {"돌기면 -y 1": (PL1, "h12_1")}, rivet=True)    # 책이 꽂아 둔 모양(판에 서 있음) — 135도 프레임이 위에서 내려오며 화살표 3개
RV3b = s3.attach("리벳", np.eye(3), {"돌기면 -y 1": (PL1, "h15_1")}, rivet=True)
RV3c = s3.attach("리벳", np.eye(3), {"돌기면 -y 1": (FR90, "h1")}, rivet=True)
FR2 = s3.recv("135도 프레임", R_FR1, {"h8": (RV3a, "p2"), "h5": (RV3b, "p2"), "h1": (RV3c, "p2")}, hover=60)
A.steps[2].cam = (-0.70, 0.89, False, None, None, None); A.steps[2].camSrc = "guess"   # 03_F(새 135도 프레임 구멍 9개, 눈으로 찍은 점) 평면 PnP: 오차 2.56px(>2 — 참고값), roll −8.9° — 화면에서 책 3번과 맞춘다
# ── 4 ── 교재 40쪽 4 (읽은 것 2026-10-15 — 3번 결과 + 12볼트 2개·너트 2개: 책 4번에서 3번과 달라진 곳 = 노란 링 2곳에 아래에서 12볼트, 위에서 너트)
#   책 4번: 새 135도 프레임이 내려앉아 리벳 3개 머리가 그 구멍에 보인다(h8·h5·h1). 노란 링 2개 = 그 프레임의 리벳 사이 구멍 h7(긴 팔, h8·h5 사이)과 짧은 팔 h2. 12볼트 2개는 아래에서 위로, 너트 2개는 위에서 내려온다.
s4 = SKEL[3]; s4.kw.pop("noPart", None)
s4.note = "[교재 4] 135도 프레임 두 장이 겹친 곳의 노란 구멍 2곳(긴 팔 리벳 사이 구멍·짧은 팔 둘째 구멍)에 아래에서 12볼트를 끼우고 위에서 너트를 조여요. ※ 1~4번은 2개 만들기."
R_FLIP = np.diag([1.0, -1.0, -1.0])   # x축 180° — 볼트는 머리가 아래·나사 끝이 위, 너트는 돌기가 아래
BO4 = [s4.attach("12볼트", R_FLIP, {"p1": (FR1, _h)}, hover=40) for _h in ("h7", "h2")]
NU4 = [s4.attach("너트", R_FLIP, {"p1": (FR2, _h)}, hover=60) for _h in ("h7", "h2")]
A.meta["lift"] = {**(A.meta.get("lift") or {}), "4": 42.0}   # 4번: 12볼트가 프레임 아래 41.8mm 에서 올라오므로 화면 전체를 42mm 띄워 시작 자리가 바닥 아래로 가지 않게
A.meta["lift"].update({str(_i): 2.0 for _i in range(5, 41)})   # 5번~: 4번에서 끼운 12볼트 머리가 프레임 아래 1.8mm 에 있으므로 화면 전체를 2mm 띄운다
A.meta["lift"].update({str(_i): 43.0 for _i in range(8, 41)})   # 8번~: 8번에서 끼운 축(길이 65)이 판 아래 35mm 까지 나가므로 화면 전체를 37mm 띄운다
